<?php
class Horario{function __construct(private PDO $db){} function obtenerTodos($b=''){ $s=$this->db->prepare("SELECT h.*,m.nombre materia,CONCAT(d.nombre,' ',d.apellidos) docente FROM horarios h JOIN materias m ON m.id=h.materia_id JOIN docentes d ON d.id=h.docente_id WHERE m.nombre LIKE ? OR h.dia LIKE ? OR h.aula LIKE ? ORDER BY h.id DESC");$x="%$b%";$s->execute([$x,$x,$x]);return $s->fetchAll();} function obtenerPorId($id){$s=$this->db->prepare("SELECT * FROM horarios WHERE id=?");$s->execute([$id]);return $s->fetch()?:null;} function insertar($d){return $this->db->prepare("INSERT INTO horarios(materia_id,docente_id,dia,hora_inicio,hora_fin,aula) VALUES(?,?,?,?,?,?)")->execute([$d['materia_id'],$d['docente_id'],$d['dia'],$d['hora_inicio'],$d['hora_fin'],$d['aula']]);} function actualizar($d){return $this->db->prepare("UPDATE horarios SET materia_id=?,docente_id=?,dia=?,hora_inicio=?,hora_fin=?,aula=? WHERE id=?")->execute([$d['materia_id'],$d['docente_id'],$d['dia'],$d['hora_inicio'],$d['hora_fin'],$d['aula'],$d['id']]);} function eliminar($id){return $this->db->prepare("DELETE FROM horarios WHERE id=?")->execute([$id]);} function materias(){return $this->db->query("SELECT id,clave,nombre FROM materias ORDER BY nombre")->fetchAll();} function docentes(){return $this->db->query("SELECT id,nombre,apellidos FROM docentes ORDER BY apellidos")->fetchAll();}}